# (topic, level v|b|i, title, code, explanation)  level: v = very basic, b = basic, i = intermediate
EX = []
def E(t, l, title, code, why): EX.append(dict(t=t, l=l, title=title, code=code.strip('\n'), why=why))

# ---------------- variables
E('var','v','Create and print a variable','name=Riya\necho "Hello, $name"','No spaces around =. Use $name to read it.')
E('var','v','Change a variable','city=Pune\ncity=Mumbai\necho "$city"','The newest value wins.')
E('var','v','Numbers are text until you do maths','a=5\necho "$a + 1"','echo just prints text; maths comes later with $(( )).')
E('var','v','Spaces need quotes','full="Asha Rao"\necho "$full"','Without quotes Bash would try to run a command called Rao.')
E('var','v','The space-around-= mistake','name = Riya 2>&1 || echo "error: Bash ran a command called name"','name = Riya means: run the command name with arguments.')
E('var','b','Curly braces separate the name','fruit=apple\necho "${fruit}s and ${fruit}_juice"','${fruit}s, not $fruits (that would be another variable).')
E('var','b','Empty and unset variables','x=""\necho "x=[$x] y=[$y]"','Both print as empty. Use set -u in scripts to catch typos.')
E('var','b','Default values','echo "port=${PORT:-8080}"\nPORT=9090\necho "port=${PORT:-8080}"',':- gives a default when the variable is empty or unset.')
E('var','b','Command output into a variable','today=$(date -d 2026-11-12 +%A)\necho "Today is $today"','$( ) runs the command and keeps its output.')
E('var','b','readonly constants','readonly MAX=3\n( MAX=4 ) 2>&1 || echo "MAX stays $MAX"','A readonly variable cannot be changed.')
E('var','b','unset removes a variable','tmp=hello\nunset tmp\necho "tmp=[${tmp:-gone}]"','After unset it no longer exists.')
E('var','i','Environment variables and export','LOCAL=1; export SHARED=2\nbash -c \'echo "child sees LOCAL=[$LOCAL] SHARED=[$SHARED]"\'','Only exported variables reach child programs.')
E('var','i','Special variables','set -- apple banana\necho "count=$# first=$1 all=$@"\nfalse; echo "last status=$?"','$# count, $1 first, $@ all arguments, $? last exit status.')
E('var','i','Variable in a single-quoted string','name=Riya\necho \'Hello $name\'\necho "Hello $name"','Single quotes print exactly; double quotes expand.')

# ---------------- data types
E('type','v','Everything is a string by default','x=10\ny=abc\necho "$x and $y"','Bash has no int/float/string keywords for normal variables.')
E('type','v','Integer maths with $(( ))','a=7; b=3\necho "sum=$((a+b)) product=$((a*b))"','Inside $(( )) no $ is needed.')
E('type','b','Integer division drops decimals','echo "$(( 7 / 2 ))"','Bash maths is whole numbers only.')
E('type','b','Decimals with bc','echo "scale=2; 7/2" | bc','bc does decimal maths; scale = digits after the point.')
E('type','b','declare -i makes an integer variable','declare -i n=5\nn=n+10\necho "$n"','With -i, assignments are calculated.')
E('type','b','Indexed array','fruits=(apple banana mango)\necho "${fruits[0]} ${fruits[2]}"\necho "count: ${#fruits[@]}"','Index starts at 0.')
E('type','b','Add to an array','list=(a b)\nlist+=(c)\necho "${list[@]}"','+= appends.')
E('type','i','Associative array (key → value)','declare -A price=([tea]=10 [coffee]=25)\necho "tea costs ${price[tea]}"\nprice[juice]=40\necho "items: $(printf \'%s\\n\' "${!price[@]}" | sort | paste -sd\' \')"','declare -A is required. ${!price[@]} lists keys.')
E('type','i','Lowercase / uppercase variables','declare -u up=pune; declare -l low=MUMBAI\necho "$up $low"','-u and -l convert automatically.')
E('type','i','Check the type of a variable','declare -a arr=(1 2); declare -A map=([k]=v); declare -i num=3\ndeclare -p arr map num','declare -p shows how a variable was declared.')
E('type','i','Is it a number?','for v in 42 -7 3.5 abc; do\n  if [[ $v =~ ^-?[0-9]+$ ]]; then echo "$v: integer"; else echo "$v: not an integer"; fi\ndone','A regex check, because everything is text.')

# ---------------- operators
E('op','v','Arithmetic operators','a=17; b=5\necho "+ $((a+b))  - $((a-b))  * $((a*b))  / $((a/b))  % $((a%b))"','% is the remainder.')
E('op','v','Power','echo "2 to the 10 = $((2**10))"','** is power.')
E('op','b','Increment and decrement','n=5\n((n++)); echo "$n"\n((n--)); ((n--)); echo "$n"','++ adds 1, -- subtracts 1.')
E('op','b','Short assignment operators','x=10\n((x += 5)); echo "$x"\n((x *= 2)); echo "$x"','+= -= *= /= work inside (( )).')
E('op','b','Number comparison in (( ))','a=8; b=12\n(( a < b )) && echo "a is smaller"\n(( a == 8 )) && echo "a is 8"','Inside (( )) use < > == != <= >=.')
E('op','b','Number comparison in [ ]','a=8; b=12\n[ "$a" -lt "$b" ] && echo "-lt: less than"\n[ "$a" -ne "$b" ] && echo "-ne: not equal"','-eq -ne -lt -le -gt -ge inside [ ] and [[ ]].')
E('op','b','String comparison','s=apple\n[[ $s == apple ]] && echo "equal"\n[[ $s != mango ]] && echo "not mango"\n[[ $s < banana ]] && echo "apple sorts before banana"','== != < > compare text.')
E('op','b','Empty or not','s=""\n[[ -z $s ]] && echo "-z: empty"\ns=hi\n[[ -n $s ]] && echo "-n: not empty"','-z empty, -n not empty.')
E('op','b','Logical AND, OR, NOT','age=25\n[[ $age -ge 18 && $age -lt 60 ]] && echo "working age"\n[[ ! $age -lt 18 ]] && echo "not a minor"','&& and, || or, ! not.')
E('op','i','File test operators','mkdir -p d; touch f.txt\n[[ -e f.txt ]] && echo "-e exists"\n[[ -f f.txt ]] && echo "-f regular file"\n[[ -d d ]] && echo "-d directory"\n[[ -s f.txt ]] || echo "-s false: file is empty"','-e -f -d -s -r -w -x test files.')
E('op','i','Pattern match with ==','f=report.csv\n[[ $f == *.csv ]] && echo "a CSV file"\n[[ $f == r* ]] && echo "starts with r"','Unquoted right side = glob pattern.')
E('op','i','Regex match =~','email=asha@example.com\n[[ $email =~ ^[^@]+@[^@]+\\.[a-z]+$ ]] && echo "looks like an email"','=~ uses regular expressions.')
E('op','i','Ternary-style expression','n=7\necho "$(( n % 2 == 0 ? 0 : 1 )) -> 1 means odd"\nmax=$(( 4 > 9 ? 4 : 9 )); echo "max=$max"','cond ? a : b inside $(( )).')
E('op','i','Bitwise operators','echo "5&3=$((5&3)) 5|3=$((5|3)) 5^3=$((5^3)) 1<<4=$((1<<4))"','& | ^ << >> work on bits.')

# ---------------- input / output
E('io','v','echo and printf','echo "Hello"\nprintf "Hello %s, you are %d\\n" Riya 25','printf gives exact formatting.')
E('io','v','Read input from the user','read -r name <<< "Riya"   # in a real terminal: read -r name\necho "Hi $name"','read stores one line of input.')
E('io','b','Prompt in the same line','read -r -p "City: " city <<< "Pune"\necho "You chose $city"','-p shows a prompt.')
E('io','b','Read several values','read -r first last <<< "Asha Rao"\necho "first=$first last=$last"','Words are split into the variables.')
E('io','b','printf columns','printf "%-8s %5s\\n" Item Price\nprintf "%-8s %5d\\n" tea 10 coffee 25','- left-aligns; numbers give the width.')
E('io','b','Decimals with printf','printf "%.2f\\n" 3.14159','%.2f = 2 decimal places.')
E('io','i','Hidden input (passwords)','read -r -s pw <<< "secret"; echo "length ${#pw} (not shown)"','-s does not echo what you type.')
E('io','i','Write to a file and append','echo "line 1" > notes.txt\necho "line 2" >> notes.txt\ncat notes.txt','> overwrite, >> append.')
E('io','i','Here-document','cat <<EOF\nName: Riya\nCity: Pune\nEOF','Several lines of input at once.')

# ---------------- conditions
E('if','v','A simple if','age=20\nif [ "$age" -ge 18 ]; then\n  echo "adult"\nfi','then … fi; spaces inside [ ] are required.')
E('if','v','if / else','n=7\nif (( n % 2 == 0 )); then\n  echo "even"\nelse\n  echo "odd"\nfi','else runs when the test is false.')
E('if','b','if / elif / else','marks=72\nif (( marks >= 90 )); then grade=A\nelif (( marks >= 75 )); then grade=B\nelif (( marks >= 60 )); then grade=C\nelse grade=F\nfi\necho "grade $grade"','The first true branch wins.')
E('if','b','Check a file before using it','f=data.txt\nif [[ -f $f ]]; then echo "reading $f"; else echo "$f is missing"; fi','A very common start of scripts.')
E('if','b','Combine conditions','user=admin; pass=ok\nif [[ $user == admin && $pass == ok ]]; then echo "welcome"; fi','&& inside [[ ]].')
E('if','b','Nested if','temp=35; humid=80\nif (( temp > 30 )); then\n  if (( humid > 70 )); then echo "hot and humid"; else echo "hot and dry"; fi\nfi','An if inside an if.')
E('if','b','One-line if with && and ||','n=5\n(( n > 3 )) && echo "big" || echo "small"','Short form; keep it for simple cases.')
E('if','i','Test a command’s success','if grep -q root /etc/passwd; then echo "root user exists"; fi','if checks the exit status of any command.')
E('if','i','Negate a command','if ! command -v nosuchtool >/dev/null; then echo "nosuchtool is not installed"; fi','! reverses success/failure.')
E('if','i','Leap year','for y in 2024 1900 2000 2026; do\n  if (( (y%4==0 && y%100!=0) || y%400==0 )); then echo "$y leap"; else echo "$y not leap"; fi\ndone','Combined arithmetic conditions.')

# ---------------- case
E('case','v','A simple case','day=Sat\ncase $day in\n  Sat|Sun) echo "weekend" ;;\n  *) echo "weekday" ;;\nesac','| means or; * is the default.')
E('case','b','Menu choice','choice=2\ncase $choice in\n  1) echo "start" ;;\n  2) echo "stop" ;;\n  3) echo "restart" ;;\n  *) echo "invalid" ;;\nesac','Each branch ends with ;;')
E('case','b','Patterns with wildcards','for f in a.jpg b.PNG c.txt d.tar.gz; do\n  case $f in\n    *.jpg|*.png|*.PNG) echo "$f: image" ;;\n    *.tar.gz) echo "$f: archive" ;;\n    *) echo "$f: other" ;;\n  esac\ndone','Glob patterns, not regex.')
E('case','b','yes / no answers','for ans in y YES no maybe; do\n  case ${ans,,} in\n    y|yes) echo "$ans -> yes" ;;\n    n|no) echo "$ans -> no" ;;\n    *) echo "$ans -> please answer yes or no" ;;\n  esac\ndone','${ans,,} lowercases first.')
E('case','i','Character classes','for c in a 7 Z %; do\n  case $c in\n    [a-z]) echo "$c lowercase" ;;\n    [A-Z]) echo "$c uppercase" ;;\n    [0-9]) echo "$c digit" ;;\n    *) echo "$c symbol" ;;\n  esac\ndone','[ ] matches one character.')
E('case','i','Fall through with ;&','n=1\ncase $n in\n  1) echo "one" ;&\n  2) echo "...and also runs the next branch" ;;\nesac',';& continues into the next branch.')

# ---------------- loops
E('loop','v','for over a list','for fruit in apple banana mango; do\n  echo "I like $fruit"\ndone','One round per item.')
E('loop','v','for over numbers','for i in 1 2 3 4 5; do echo -n "$i "; done; echo','echo -n stays on the line.')
E('loop','v','Brace range','for i in {1..5}; do echo -n "$i "; done; echo\nfor i in {10..0..5}; do echo -n "$i "; done; echo','{start..end..step}.')
E('loop','b','C-style for','for (( i=1; i<=5; i++ )); do echo -n "$((i*i)) "; done; echo','Like C/Java: init; test; step.')
E('loop','b','while loop','n=1\nwhile (( n <= 3 )); do\n  echo "round $n"\n  ((n++))\ndone','Repeats while the test is true.')
E('loop','b','until loop','n=3\nuntil (( n == 0 )); do echo "countdown $n"; ((n--)); done','Repeats until the test becomes true.')
E('loop','b','break and continue','for i in {1..10}; do\n  (( i % 2 == 0 )) && continue\n  (( i > 7 )) && break\n  echo -n "$i "\ndone; echo','continue skips this round; break leaves the loop.')
E('loop','b','Loop over files','touch a.log b.log c.txt\nfor f in *.log; do echo "found $f"; done','Globs give file names safely.')
E('loop','b','Loop over an array','langs=(Bash Python "Shell Script")\nfor l in "${langs[@]}"; do echo "- $l"; done','Quote "${arr[@]}" to keep items with spaces.')
E('loop','b','Read a file line by line','printf "web01\\nweb02\\ndb01\\n" > hosts.txt\nwhile IFS= read -r h; do echo "host: $h"; done < hosts.txt','The safe way to read lines.')
E('loop','i','Sum 1..100','sum=0\nfor (( i=1; i<=100; i++ )); do (( sum += i )); done\necho "sum=$sum"','Accumulate in a variable.')
E('loop','i','Multiplication table','n=7\nfor i in {1..5}; do printf "%d x %d = %2d\\n" "$n" "$i" $((n*i)); done','printf keeps it aligned.')
E('loop','i','Nested loops: a pattern','for (( r=1; r<=4; r++ )); do\n  for (( c=1; c<=r; c++ )); do echo -n "* "; done\n  echo\ndone','Outer = rows, inner = columns.')
E('loop','i','Loop with index and value','colors=(red green blue)\nfor i in "${!colors[@]}"; do echo "$i: ${colors[i]}"; done','${!arr[@]} gives the indexes.')
E('loop','i','Infinite loop with a stop condition','n=0\nwhile true; do\n  (( n++ ))\n  (( n == 4 )) && { echo "stopped at $n"; break; }\ndone','while true + break.')
E('loop','i','Retry until success','try=0\nconnect() { (( ++try >= 3 )); }   # pretend it works on the 3rd try\nuntil connect; do echo "try $try failed, retrying"; done\necho "connected on try $try"','until repeats while the command fails.')

# ---------------- functions
E('fn','v','Define and call a function','greet() {\n  echo "Hello!"\n}\ngreet\ngreet','Define once, call by name.')
E('fn','v','Function with an argument','greet() { echo "Hello, $1"; }\ngreet Riya\ngreet Arjun','$1 is the first argument of the function.')
E('fn','b','Several arguments','add() { echo "$1 + $2 = $(( $1 + $2 ))"; }\nadd 3 4','$1 $2 … inside the function.')
E('fn','b','Return a value with echo','square() { echo $(( $1 * $1 )); }\nresult=$(square 9)\necho "result=$result"','Print it, capture with $( ).')
E('fn','b','return gives a status (0–255)','is_even() { (( $1 % 2 == 0 )); }\nfor n in 4 7; do if is_even "$n"; then echo "$n even"; else echo "$n odd"; fi; done','return/exit status means success or failure.')
E('fn','b','local variables','x=global\nf() { local x=inside; echo "in f: $x"; }\nf; echo "outside: $x"','local keeps the variable inside the function.')
E('fn','b','Default argument','greet() { local name=${1:-friend}; echo "Hi $name"; }\ngreet; greet Meera','${1:-default}.')
E('fn','i','Count and loop over all arguments','show() { echo "$# args"; for a in "$@"; do echo " - $a"; done; }\nshow one "two words" three','"$@" keeps each argument separate.')
E('fn','i','Recursion: factorial','fact() { (( $1 <= 1 )) && { echo 1; return; }; echo $(( $1 * $(fact $(( $1 - 1 ))) )); }\nfact 5','A function calling itself.')
E('fn','i','Function that validates input','is_number() { [[ $1 =~ ^[0-9]+$ ]]; }\nfor v in 12 x9; do is_number "$v" && echo "$v ok" || echo "$v not a number"; done','Use the status in if / && / ||.')
E('fn','i','Return an array (via echo)','evens() { local i; for (( i=2; i<=$1; i+=2 )); do echo "$i"; done; }\nmapfile -t e < <(evens 10)\necho "${#e[@]} evens: ${e[*]}"','One value per line, collect with mapfile.')
E('fn','i','Pass an array by name','sum() { local -n arr=$1; local s=0 v; for v in "${arr[@]}"; do (( s += v )); done; echo "$s"; }\nnums=(4 8 15)\nsum nums','local -n is a reference to another variable.')

# ---------------- strings
E('str','v','Length of a string','s=Mumbai\necho "${#s}"','${#var} = number of characters.')
E('str','b','Substring','s=2026-11-12\necho "year=${s:0:4} month=${s:5:2}"','${var:start:length}.')
E('str','b','Replace text','s="I like tea"\necho "${s/tea/coffee}"\np=a-b-c; echo "${p//-/_}"','/ first match, // all.')
E('str','b','Upper and lower case','s=Pune\necho "${s^^} ${s,,}"','^^ upper, ,, lower.')
E('str','b','Remove a prefix or suffix','f=/home/riya/report.tar.gz\necho "${f##*/}"\necho "${f%%.*}"','# from the start, % from the end.')
E('str','i','Split a string into an array','IFS=, read -r -a parts <<< "red,green,blue"\necho "${parts[1]} (${#parts[@]} parts)"','IFS sets the separator.')
E('str','i','Join an array into a string','a=(x y z)\n( IFS=-; echo "${a[*]}" )','${arr[*]} joins with the first IFS character.')
E('str','i','Contains a word?','s="error: disk full"\n[[ $s == *disk* ]] && echo "mentions disk"','Glob match.')
E('str','i','Reverse a string','s=Bash; r=""\nfor (( i=${#s}-1; i>=0; i-- )); do r+=${s:i:1}; done\necho "$r"','Loop over characters backwards.')
E('str','i','Trim spaces','s="   hello   "\nt=${s#"${s%%[![:space:]]*}"}; t=${t%"${t##*[![:space:]]}"}\necho "[$t]"','Pure Bash trim.')

# ---------------- small programs
E('prog','b','Even or odd checker','for n in 3 10 21; do (( n % 2 )) && echo "$n odd" || echo "$n even"; done','Loop + condition.')
E('prog','b','Largest of three','a=12 b=45 c=27; max=$a\n(( b > max )) && max=$b\n(( c > max )) && max=$c\necho "largest=$max"','Compare and keep the biggest.')
E('prog','b','Simple calculator','calc() { case $2 in +) echo $(( $1 + $3 ));; -) echo $(( $1 - $3 ));; x) echo $(( $1 * $3 ));; /) echo $(( $1 / $3 ));; esac; }\ncalc 12 + 5; calc 12 x 5; calc 12 / 5','case + arithmetic.')
E('prog','i','Fibonacci','a=0 b=1\nfor i in {1..10}; do echo -n "$a "; (( t = a + b, a = b, b = t )); done; echo','Comma does several operations.')
E('prog','i','Prime numbers up to 30','for (( n=2; n<=30; n++ )); do\n  p=1; for (( d=2; d*d<=n; d++ )); do (( n % d == 0 )) && { p=0; break; }; done\n  (( p )) && echo -n "$n "\ndone; echo','Nested loop with break.')
E('prog','i','Word count per word','text="to be or not to be"\ndeclare -A c; for w in $text; do (( c[$w]++ )); done\nfor w in "${!c[@]}"; do echo "$w ${c[$w]}"; done | sort','Associative array as a counter.')
E('prog','i','Palindrome check','for w in level madam bash; do r=$(rev <<< "$w"); [[ $w == "$r" ]] && echo "$w: palindrome" || echo "$w: not"; done','rev reverses text.')
E('prog','i','Grade report from a list','while read -r name marks; do\n  if (( marks >= 75 )); then g=Distinction; elif (( marks >= 40 )); then g=Pass; else g=Fail; fi\n  printf "%-6s %3d  %s\\n" "$name" "$marks" "$g"\ndone <<< $\'Asha 82\\nRavi 55\\nMeera 31\'','Read + if/elif + printf together.')
